{"implementation":"from fractions import Fraction


def _bounded_largest_remainder(amount, weights, limits):
    n = len(limits)
    result = [0] * n
    remaining = int(amount)
    limits = [max(0, int(x)) for x in limits]
    weights = [int(w) for w in weights]

    while remaining > 0:
        active = [i for i in range(n) if limits[i] > 0]
        if not active:
            break

        positive_weight = any(weights[i] > 0 for i in active)
        if positive_weight:
            work_weights = [weights[i] if weights[i] > 0 else 0 for i in range(n)]
        else:
            work_weights = [1 if limits[i] > 0 else 0 for i in range(n)]

        total_weight = sum(work_weights[i] for i in active)
        if total_weight <= 0:
            break

        quotas = {}
        base_sum = 0
        capped = False
        for i in active:
            quota = Fraction(remaining * work_weights[i], total_weight)
            base = quota.numerator // quota.denominator
            if base > limits[i]:
                base = limits[i]
                capped = True
            quotas[i] = quota
            if base:
                result[i] += base
                limits[i] -= base
                base_sum += base

        remaining -= base_sum
        if remaining <= 0:
            break

        if capped and base_sum > 0:
            continue

        order = sorted(
            (i for i in active if limits[i] > 0),
            key=lambda i: (quotas[i] - (quotas[i].numerator // quotas[i].denominator), work_weights[i], -i),
            reverse=True,
        )
        if not order:
            break

        progressed = False
        for i in order:
            if remaining <= 0:
                break
            if limits[i] <= 0:
                continue
            result[i] += 1
            limits[i] -= 1
            remaining -= 1
            progressed = True

        if not progressed:
            break

    return result


def solve(case):
    segments = list(case.get("segments", []))
    budget = max(0, int(case.get("budget", 0)))
    n = len(segments)

    names = [seg.get("name") for seg in segments]
    minimums = [max(0, int(seg.get("minimum", 0))) for seg in segments]
    capacities = [max(0, int(seg.get("capacity", 0))) for seg in segments]
    importance = [int(seg.get("importance", 0)) for seg in segments]

    floors = [min(minimums[i], capacities[i]) for i in range(n)]
    total_capacity = sum(capacities)
    target_total = min(budget, total_capacity)

    if target_total <= sum(floors):
        allocations = _bounded_largest_remainder(target_total, floors, floors)
    else:
        allocations = floors[:]
        remaining = target_total - sum(allocations)
        headroom = [capacities[i] - allocations[i] for i in range(n)]
        extras = _bounded_largest_remainder(remaining, importance, headroom)
        allocations = [allocations[i] + extras[i] for i in range(n)]

    by_name = {names[i]: allocations[i] for i in range(n)}
    return {"allocations": allocations, "by_name": by_name, "total": sum(allocations)}
"}
